module.exports = [{"id":"F001","no":1,"name":"桂枝汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳中风证","composition":[{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"甘草","gram":6,"processing":"炙"}],"pathogenesis":"风邪袭表，卫气受伤，营卫不和，腠理开泄，卫外不固","standardSymptom":"头痛发热，汗出恶风，鼻鸣干呕，苔白不渴，脉浮缓","variants":["感冒后老出汗怕风，头沉沉的还有点发烧，嗓子眼里拱着恶心。","时不时一阵热一阵汗，一见风就缩脖子，鼻子不通气干呕。","身上潮乎乎的，风吹着就冷，头发烫但汗不多，舌苔白白的。"],"differentials":["麻黄汤","桂枝加葛根汤"],"difficulty":"入门","tags":["头痛","发热","汗出","恶风","鼻鸣","干呕"]},{"id":"F002","no":2,"name":"麻黄汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳伤寒证","composition":[{"herb":"麻黄","gram":9,"processing":""},{"herb":"桂枝","gram":6,"processing":""},{"herb":"杏仁","gram":9,"processing":"去皮尖"},{"herb":"甘草","gram":3,"processing":"炙"}],"pathogenesis":"寒邪束表，卫阳被遏，营阴郁滞，肺气不宣","standardSymptom":"恶寒发热，无汗而喘，头身疼痛，舌淡苔薄白，脉浮紧","variants":["冻着了，浑身发冷发烧，一点汗都没有，胸口闷得慌喘不上气。","感冒特别怕冷，裹厚被子都不行，浑身骨头节疼，不出汗。","受了寒之后体温高，皮肤干绷绷的，呼吸有点急促。"],"differentials":["桂枝汤","大青龙汤"],"difficulty":"入门","tags":["恶寒","发热","无汗","喘","身痛"]},{"id":"F003","no":3,"name":"大青龙汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳伤寒表实不解","composition":[{"herb":"麻黄","gram":12,"processing":""},{"herb":"桂枝","gram":6,"processing":""},{"herb":"杏仁","gram":9,"processing":"去皮尖"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"石膏","gram":30,"processing":"碎"}],"pathogenesis":"风寒外束，卫阳郁遏，毛窍闭塞，阳郁化热，表寒里热","standardSymptom":"恶寒发热，寒热俱重，身疼痛，不汗出而烦躁，舌红苔薄黄，脉浮紧","variants":["冻着了恶寒发热都特别重，身上疼得厉害还不出一点汗，心里烦躁得不行。","高烧怕冷一样都不轻，浑身骨节疼，汗憋着出不来，人在屋里躁得要命。","寒战发高烧，浑身疼，皮肤干绷绷的没一滴汗，烦躁得坐卧不宁。"],"differentials":["麻黄汤","小青龙汤","桂枝汤"],"difficulty":"进阶","tags":["恶寒","发热","无汗","烦躁","口渴"]},{"id":"F004","no":4,"name":"小青龙汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳伤寒，水气内停","composition":[{"herb":"麻黄","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"细辛","gram":3,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"桂枝","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":"洗"},{"herb":"五味子","gram":9,"processing":""}],"pathogenesis":"风寒客表，水饮内停，寒饮射肺，表寒里饮同病，素体阳虚","standardSymptom":"恶寒发热，无汗，喘咳，痰多而稀，或不得平卧，身体疼重，舌苔白滑，脉浮","variants":["一着凉就咳喘，痰稀白沫样的很难咳出，躺着更喘得厉害只好坐着。","感冒不出汗，咳嗽带喘，痰像清清的白沫子，身上沉得像灌了铅。","受寒后憋得喘不过气，痰跟蛋清似的又白又黏，躺不下只能半靠着。"],"differentials":["麻黄汤","大青龙汤","桂枝加厚朴杏仁汤"],"difficulty":"进阶","tags":["恶寒","无汗","喘咳","痰稀","苔白滑","不得平卧"]},{"id":"F005","no":5,"name":"桂枝麻黄各半汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳伤寒、中风并见","composition":[{"herb":"桂枝","gram":5,"processing":""},{"herb":"芍药","gram":5,"processing":""},{"herb":"生姜","gram":5,"processing":""},{"herb":"甘草","gram":5,"processing":"炙"},{"herb":"麻黄","gram":5,"processing":""},{"herb":"杏仁","gram":5,"processing":"去皮尖"},{"herb":"大枣","gram":4,"processing":"擘"}],"pathogenesis":"表邪轻浅，营卫不和，寒风并中，小发其汗","standardSymptom":"发热恶寒，热多寒少，身痒，面有热色，无汗或微汗，舌淡红苔薄白，脉微弱","variants":["烧得不厉害但总反复，怕冷又怕热，身上痒痒的像有小虫爬。","脸红红的发烧，冷一阵热一阵，皮肤干痒不出汗。","感冒拖着好不利索，身上刺挠，汗出一点点就不痒了。"],"differentials":["桂枝汤","麻黄汤","桂枝二麻黄一汤"],"difficulty":"进阶","tags":["发热","恶寒","身痒","微汗"]},{"id":"F006","no":6,"name":"葛根汤","alias":[],"source":"伤寒论","meridians":["太阳","阳明"],"subPattern":"太阳阳明合病","composition":[{"herb":"葛根","gram":12,"processing":""},{"herb":"麻黄","gram":9,"processing":""},{"herb":"桂枝","gram":6,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"芍药","gram":6,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"}],"pathogenesis":"风寒客表，经气不利，项背拘急，邪及阳明","standardSymptom":"恶寒发热，无汗，项背强痛，头痛，下利或呕，舌淡苔薄白，脉浮紧","variants":["脖子后头那根筋绷得紧紧的，转头都费劲，还发烧不出汗。","后背连着后颈酸硬得像板子，怕冷发烧，有点拉肚子。","受寒后脑袋和后背疼得厉害，汗闷在里头出不来。"],"differentials":["桂枝加葛根汤","麻黄汤","大青龙汤"],"difficulty":"进阶","tags":["恶寒","无汗","项背强","头痛","下利"]},{"id":"F007","no":7,"name":"麻黄加术汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳伤寒表实身痛","composition":[{"herb":"麻黄","gram":9,"processing":""},{"herb":"桂枝","gram":6,"processing":""},{"herb":"杏仁","gram":9,"processing":"去皮尖"},{"herb":"甘草","gram":3,"processing":"炙"},{"herb":"白术","gram":12,"processing":""}],"pathogenesis":"寒湿在表，营卫郁滞，一身烦疼，表实兼湿","standardSymptom":"恶寒发热，无汗，身体烦疼，关节酸痛沉重，舌淡苔白，脉浮紧","variants":["浑身酸沉得要命，骨头缝都疼，怕冷发烧还一点汗没有。","着了寒湿，浑身上下烦疼，关节沉甸甸的，不出汗。","发烧怕冷不出汗，可身上疼得坐卧不宁，像灌了铅。"],"differentials":["麻黄汤","桂枝加芍药汤","麻杏苡甘汤"],"difficulty":"难点","tags":["恶寒","无汗","身痛","关节酸沉"]},{"id":"F008","no":8,"name":"麻黄细辛附子汤","alias":[],"source":"伤寒论","meridians":["少阴","太阳"],"subPattern":"少阴病，始得之，反发热，太少两感","composition":[{"herb":"麻黄","gram":6,"processing":""},{"herb":"细辛","gram":3,"processing":""},{"herb":"附子","gram":9,"processing":"炮"}],"pathogenesis":"少阴阳虚，外感风寒，太少两感，表里俱寒","standardSymptom":"恶寒发热，无汗，神疲欲寐，四肢不温，舌淡苔白，脉沉微","variants":["本来就虚，这回受寒发烧怕冷，人困得睁不开眼，手脚冰凉。","身体底子弱，一感冒就高烧畏寒不出汗，总想缩着睡。","受凉后浑身冷得厉害，没精神只想躺着，脉摸着沉沉的。"],"differentials":["麻黄汤","桂枝人参汤","四逆汤"],"difficulty":"难点","tags":["恶寒","发热","无汗","神疲","肢冷"]},{"id":"F009","no":9,"name":"桂枝加葛根汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳中风项背强","composition":[{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"葛根","gram":12,"processing":""}],"pathogenesis":"风邪袭表，营卫不和，经气不舒，项背拘急","standardSymptom":"发热恶风，汗出，项背强痛，头痛，舌淡红苔薄白，脉浮缓","variants":["感冒老出汗怕风，后脖颈那一块硬邦邦的，扭头都僵。","低烧冒虚汗，风一吹就冷，后背连着脖子酸得直不起来。","受了风身上潮乎乎的，后颈僵疼，人软绵绵没力气。"],"differentials":["桂枝汤","葛根汤","桂枝加厚朴杏仁汤"],"difficulty":"进阶","tags":["发热","恶风","汗出","项背强"]},{"id":"F010","no":10,"name":"桂枝加厚朴杏仁汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳中风，喘息胁痛","composition":[{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"厚朴","gram":6,"processing":"炙"},{"herb":"杏仁","gram":9,"processing":"去皮尖"}],"pathogenesis":"风邪袭表，营卫不和，肺气上逆，兼喘胁痛","standardSymptom":"发热恶风，汗出，喘息，胸闷，舌淡红苔薄白，脉浮缓","variants":["感冒出着汗还怕风，喘得厉害，气儿总不够用，胸口发闷。","受了风就冒虚汗，一动就喘，嗓子和胸口都发紧。","低烧怕风出汗，喘得凶，胸口像压了块石头透不过气。"],"differentials":["桂枝汤","小青龙汤","桂枝加葛根汤"],"difficulty":"进阶","tags":["发热","恶风","汗出","喘息","胁痛"]},{"id":"F011","no":11,"name":"桂枝加芍药汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳中风，脾虚腹痛","composition":[{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":18,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":"擘"}],"pathogenesis":"表邪未解，脾虚肝乘，腹中急痛，营阴不和","standardSymptom":"发热恶风，汗出，腹中急痛，喜按，舌淡苔薄，脉浮弦","variants":["感冒还没好透，肚子一阵阵绞着疼，揉一揉能缓点。","出着汗怕风，小腹里头抽痛，按着舒服些。","受了风肚子就咕噜咕噜疼，一阵紧一阵松，喜暖喜按。"],"differentials":["桂枝汤","桂枝加大黄汤","小建中汤"],"difficulty":"进阶","tags":["发热","恶风","汗出","腹痛","喜按"]},{"id":"F012","no":12,"name":"桂枝加大黄汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阴误下，邪陷阳明，大实痛","composition":[{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":18,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"大黄","gram":6,"processing":""}],"pathogenesis":"本太阳病误下，邪陷太阴，脾络瘀滞，兼阳明腑实，腹满大实痛，拒按便秘","standardSymptom":"发热恶风，汗出，腹满大实痛，拒按，便秘，舌红苔黄燥，脉沉实有力","variants":["感冒没好，肚子胀得硬邦邦的疼，碰都不敢碰，好几天没上厕所。","出着汗还怕冷，小肚子又胀又痛，按下去更狠，大便干结。","受了风后肚子里头实实地绞疼，拒按还便秘，人躁得很。"],"differentials":["桂枝加芍药汤","大承气汤","桂枝汤"],"difficulty":"难点","tags":["发热","恶风","腹满痛","拒按","便秘"]},{"id":"F013","no":13,"name":"桂枝人参汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳中风虚弱","composition":[{"herb":"桂枝","gram":12,"processing":""},{"herb":"甘草","gram":12,"processing":"炙"},{"herb":"白术","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"干姜","gram":9,"processing":""}],"pathogenesis":"表邪不解，里虚寒盛，脾阳受损，协热下利","standardSymptom":"发热恶寒，下利不止，心下痞硬，肢体倦怠，舌淡苔白，脉弱","variants":["感冒还发烧怕冷，可肚子总咕噜拉肚子，人软得没劲儿。","受了风身上发冷，胃脘那块堵得硬，一天跑好几趟厕所。","体虚感冒后低热畏寒，泻个不停，浑身乏得抬不动腿。"],"differentials":["桂枝汤","桂枝加芍药汤","麻黄细辛附子汤"],"difficulty":"进阶","tags":["发热","恶寒","下利","心下痞","倦怠"]},{"id":"F014","no":14,"name":"白虎汤","alias":[],"source":"伤寒论","meridians":["太阳","阳明"],"subPattern":"太阳热象内入","composition":[{"herb":"知母","gram":18,"processing":""},{"herb":"石膏","gram":30,"processing":"碎"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"粳米","gram":15,"processing":""}],"pathogenesis":"表邪化热，内传阳明，气分热盛，津液耗伤","standardSymptom":"身热，汗出，不恶寒反恶热，口渴引饮，舌红苔黄，脉洪大","variants":["烧得浑身烫，一个劲儿冒汗，心里燥得老想喝凉水。","之前怕冷，现在不怕了光发热，汗多口干，脉跳得又大又快。","表证转里头热，皮肤灼人手心脚心都热，渴得直灌水。"],"differentials":["白虎加人参汤","桂枝汤","大青龙汤"],"difficulty":"进阶","tags":["身热","汗出","恶热","口渴","脉洪大"]},{"id":"F015","no":15,"name":"苓桂术甘汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳伤寒，水气痞硬","composition":[{"herb":"茯苓","gram":12,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"}],"pathogenesis":"脾虚不运，水饮内停，气相搏结，心下痞硬","standardSymptom":"心下逆满，气上冲胸，起则头眩，脉沉紧，苔白滑","variants":["胃脘那块胀满堵得慌，一站起来就头晕眼花。","总觉得有股气往上顶到胸口，头也晕，舌头白腻腻的。","肚子里痞硬不舒，躺平还好，一起身就天旋地转。"],"differentials":["桂枝人参汤","小青龙汤","十枣汤"],"difficulty":"进阶","tags":["心下逆满","气上冲胸","头眩","苔白滑"]},{"id":"F016","no":16,"name":"小柴胡汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"邪入少阳，枢机不利（少阳病）","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":"洗"},{"herb":"甘草","gram":9,"processing":"炙"},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"}],"pathogenesis":"太阳表邪未解，内传少阳，枢机不利，正邪分争","standardSymptom":"往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，舌淡红苔薄白，脉弦","variants":["一会儿冷得发抖一会儿烧得慌，胸口两肋胀闷，吃不下饭。","老是恶心心烦，不想吃东西，肋骨两边堵得不舒服。","寒热来回折腾，口苦咽干，人闷闷的不想说话老想吐。"],"differentials":["桂枝汤","大青龙汤","白虎汤"],"difficulty":"进阶","tags":["往来寒热","胸胁苦满","不欲食","心烦喜呕"]},{"id":"F017","no":17,"name":"十枣汤","alias":[],"source":"伤寒论","meridians":["太阳"],"subPattern":"太阳水气射肺","composition":[{"herb":"芫花","gram":1,"processing":"熬"},{"herb":"甘遂","gram":1,"processing":""},{"herb":"大戟","gram":1,"processing":""},{"herb":"大枣","gram":10,"processing":"擘"}],"pathogenesis":"水饮停聚胸胁，壅塞肺气，悬饮内结，正气尚支","standardSymptom":"心下痞硬满，引胁下痛，干呕短气，咳唾引痛，苔白滑，脉沉弦","variants":["胸口到两肋胀得硬疼，一咳嗽牵着那块就钻心地痛，气也短。","嗓子里老有痰咳不净，喘不上气，肋巴骨里头刺痛。","肚子上头堵硬，干呕还喘，深呼吸两胁就扯着疼。"],"differentials":["小青龙汤","苓桂术甘汤","葶苈大枣泻肺汤"],"difficulty":"难点","tags":["心下痞硬","胁下痛","干呕","短气","咳唾引痛"]},{"id":"F018","no":18,"name":"泻白散","alias":[],"source":"医学启源","meridians":["肺"],"subPattern":"太阳热象，肺热咳嗽","composition":[{"herb":"桑白皮","gram":15,"processing":"炒"},{"herb":"地骨皮","gram":15,"processing":""},{"herb":"甘草","gram":3,"processing":"炙"},{"herb":"粳米","gram":15,"processing":""}],"pathogenesis":"肺有伏火，郁热伤阴，肺气上逆，咳喘绵绵","standardSymptom":"咳嗽气喘，皮肤蒸热，日晡尤甚，舌红苔黄，脉细数","variants":["咳个没完，气喘，皮肤摸着发烫，下午尤其厉害。","嗓子不痒就是阵阵地咳，胸口燥热，傍晚烧得明显。","老慢支似的低热咳嗽，午后身子烘烘地热，舌红少津。"],"differentials":["小青龙汤","麻杏石甘汤","白虎汤"],"difficulty":"难点","tags":["咳嗽","气喘","皮肤蒸热","日晡热","脉细数"]},{"id":"F019","no":19,"name":"白虎汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象","composition":[{"herb":"知母","gram":18,"processing":""},{"herb":"石膏","gram":30,"processing":"碎"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"粳米","gram":15,"processing":""}],"pathogenesis":"阳明气分热盛，里热炽张，津液被灼，无表邪束","standardSymptom":"壮热面赤，大汗出，大烦渴，脉洪大有力，舌红苔黄燥","variants":["烧得脸通红，汗哗哗地出，渴得要命，心口烦躁。","高热不怕冷了，反倒怕热，汗出如洗，老想喝冰水。","整个人烫得厉害，大汗淋漓，口渴引饮，脉洪得像洪水。"],"differentials":["白虎加人参汤","大承气汤","调胃承气汤"],"difficulty":"入门","tags":["壮热","大汗","大渴","脉洪大","面赤"]},{"id":"F020","no":20,"name":"白虎加人参汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，气虚","composition":[{"herb":"知母","gram":18,"processing":""},{"herb":"石膏","gram":30,"processing":"碎"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"粳米","gram":15,"processing":""},{"herb":"人参","gram":9,"processing":""}],"pathogenesis":"阳明热盛，气津两伤，热灼津亏，气虚不摄","standardSymptom":"身热汗多，大渴饮水不解，气短神疲，舌红苔黄燥，脉洪大而芤","variants":["高烧出汗，渴得不行，水灌进去也不解渴，人虚得发软。","热得慌汗出得多，越喝越渴，气短没精神，脉大却空。","阳明热盛还气虚，喝多少都渴，浑身乏力直想歇着。"],"differentials":["白虎汤","白虎加桂枝汤","大承气汤"],"difficulty":"进阶","tags":["身热","汗多","大渴","气短","脉芤"]},{"id":"F021","no":21,"name":"白虎加桂枝汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"温疟，热痹，阳明热盛（骨节疼烦）","composition":[{"herb":"知母","gram":18,"processing":""},{"herb":"石膏","gram":30,"processing":"碎"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"粳米","gram":15,"processing":""},{"herb":"桂枝","gram":9,"processing":""}],"pathogenesis":"阳明热盛，气阴两伤，复感风寒湿邪，热郁骨节，温疟骨节疼烦，或热痹肿痛","standardSymptom":"身无寒但热，骨节疼烦，时呕，汗出，口渴，舌红苔薄黄，脉弦数","variants":["一阵阵发烧浑身滚烫，骨头缝里又热又疼，还总泛恶心想吐。","里头热得慌，关节红肿灼痛，汗出得厉害老口渴，动不动就犯呕。","身上烘烘地热，浑身骨节酸灼地疼，出汗还老想喝水，时不时就呕逆。"],"differentials":["白虎汤","桂枝加葛根汤","白虎加人参汤"],"difficulty":"进阶","tags":["壮热","汗出","口渴","骨节疼"]},{"id":"F022","no":22,"name":"承气汤类","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明腑实","composition":[{"herb":"大黄","gram":12,"processing":"酒洗"},{"herb":"厚朴","gram":15,"processing":"炙"},{"herb":"枳实","gram":12,"processing":"炙"},{"herb":"芒硝","gram":9,"processing":"冲"}],"pathogenesis":"阳明腑实，燥屎内结，气机壅滞，痞满燥实坚俱备","standardSymptom":"腹满硬痛拒按，大便秘结，潮热谵语，手足濈然汗出，舌红苔黄燥，脉沉实有力（痞、满、燥、实、坚俱备，阳明腑实总纲）","variants":["下午一阵阵潮热，说胡话，肚子胀硬疼，好几天拉不出。","腑实总纲：痞满燥实全有了，腹硬拒按，大便不通，手足汗出。","热结腑中，潮热谵语，腹满痛坚，燥屎阻结，脉沉而实。"],"differentials":["小承气汤","大承气汤","调胃承气汤"],"difficulty":"入门","tags":["潮热","谵语","腹满痛","便秘","痞满燥实"]},{"id":"F023","no":23,"name":"小承气汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明腑实，轻症","composition":[{"herb":"大黄","gram":12,"processing":"酒洗"},{"herb":"厚朴","gram":6,"processing":"炙"},{"herb":"枳实","gram":9,"processing":"炙"}],"pathogenesis":"阳明腑实初起，痞满为主，燥坚未甚，轻下热结","standardSymptom":"潮热，腹胀满，大便硬，谵语，脉滑而疾，苔黄腻","variants":["肚子胀得鼓鼓的，下午一阵潮热，大便干结拉不出。","腑实轻症，腹胀满闷，有点说糊话，脉滑得快。","热结不重，主要是痞满，大便发硬，苔黄腻腻的。"],"differentials":["大承气汤","调胃承气汤","承气汤类"],"difficulty":"进阶","tags":["潮热","腹胀满","大便硬","谵语","脉滑疾"]},{"id":"F024","no":24,"name":"大承气汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明腑实，重症","composition":[{"herb":"大黄","gram":12,"processing":"酒洗"},{"herb":"厚朴","gram":15,"processing":"炙"},{"herb":"枳实","gram":12,"processing":"炙"},{"herb":"芒硝","gram":9,"processing":"冲"}],"pathogenesis":"阳明腑实重证，燥屎内结，痞满燥实坚俱盛，急下存阴","standardSymptom":"潮热谵语，腹满硬痛拒按，便秘，手足濈汗，舌红苔黄燥，脉沉实有力","variants":["烧得一阵阵潮热，胡话连篇，肚子硬得疼不敢碰，便秘厉害。","腑实重症，腹胀硬如石拒按，大便多日不通，手足汗出。","燥屎结得死紧，满腹硬痛，脉沉实有力，再不下就伤阴了。"],"differentials":["小承气汤","调胃承气汤","承气汤类"],"difficulty":"入门","tags":["潮热","谵语","腹满硬痛","便秘","脉沉实"]},{"id":"F025","no":25,"name":"调胃承气汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明腑实，未成实","composition":[{"herb":"大黄","gram":12,"processing":"酒洗"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"芒硝","gram":9,"processing":"冲"}],"pathogenesis":"阳明燥热初结，腑实未成，燥实为主，缓下和胃","standardSymptom":"蒸蒸发热，心烦，腹胀满，大便不通，舌红苔黄燥","variants":["身上一阵阵往外蒸着发热，心里烦躁，肚子胀，大便不通。","腑实未成，主要是燥热内结，心烦腹胀，热从里头发出来。","不大便而蒸热，躁扰不宁，腹微满，苔黄燥，还不到硬痛。"],"differentials":["大承气汤","小承气汤","承气汤类"],"difficulty":"进阶","tags":["蒸蒸发热","心烦","腹胀满","大便不通"]},{"id":"F026","no":26,"name":"竹叶石膏汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，气阴两伤，胃气不和","composition":[{"herb":"竹叶","gram":9,"processing":""},{"herb":"石膏","gram":30,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"麦冬","gram":15,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"粳米","gram":10,"processing":""}],"pathogenesis":"热病后期余热未清，气阴两伤。阴虚津伤则烦热口渴，气虚胃逆则气逆欲呕，舌红少苔示胃气胃阴俱损。","standardSymptom":"身热多汗，心胸烦热，气逆欲呕，口干喜饮，气短神疲，舌红少苔，脉虚数。","variants":["烧退了但这虚汗止不住，心里燥得慌，动不动就想呕，走路都没力气，舌头发红苔都快没了。","大病刚好身上还一阵阵低热，口干得厉害，胃气往上顶老想吐，人瘦了一圈没精神。","夜里汗出得凶，心里像有团火，胃气往上顶想呕，舌红少苔人软塌塌的。"],"differentials":["白虎加人参汤","白虎汤"],"difficulty":"进阶","tags":["气逆欲呕","身热多汗","舌红少苔","虚羸少气","脉虚数"]},{"id":"F027","no":27,"name":"黄连汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，心烦","composition":[{"herb":"黄连","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"上热下寒，胃中有热，腹中觉寒，寒热格拒，升降失常。","standardSymptom":"胸中烦热，腹中痛，欲呕吐，或肠鸣泄泻，舌苔白滑，脉弦。","variants":["胸口一阵阵燥热，肚子却发凉隐痛，老想吐，说不出的难受。","上边烧得慌下边肚子冷痛，犯恶心，有时肠子里咕咕响。","心烦得坐不住，胃里往上顶想吐，腹部怕冷隐隐作痛。"],"differentials":["半夏泻心汤","栀子豉汤"],"difficulty":"难点","tags":["胸中烦热","腹痛","欲呕","上热下寒"]},{"id":"F028","no":28,"name":"干姜黄连黄芩人参汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，脾虚寒热","composition":[{"herb":"干姜","gram":9,"processing":""},{"herb":"黄连","gram":9,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""}],"pathogenesis":"胃热脾寒，寒热相格，食入即吐，脾虚不运。","standardSymptom":"食入口即吐，下利便溏，口渴心烦，舌淡红苔薄黄，脉虚数。","variants":["刚吃下去就往外吐，肚子却泻得稀溏，心里还燥。","一进食就吐出来，人虚得没劲，下面却拉肚子。","胃里热得想吐，肠子却虚寒泄泻，吃饭成了折磨。"],"differentials":["半夏泻心汤","黄连汤"],"difficulty":"难点","tags":["食入即吐","下利","脾虚","寒热格","心烦"]},{"id":"F029","no":29,"name":"乌梅丸","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，虫积","composition":[{"herb":"乌梅","gram":30,"processing":"醋浸"},{"herb":"细辛","gram":3,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"黄连","gram":9,"processing":""},{"herb":"当归","gram":6,"processing":""},{"herb":"附子","gram":6,"processing":""},{"herb":"蜀椒","gram":6,"processing":""},{"herb":"桂枝","gram":6,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"黄柏","gram":6,"processing":""}],"pathogenesis":"蛔厥脏寒，上热下寒，虫动不安，寒热错杂。","standardSymptom":"腹痛阵作，心烦呕吐，得食而呕，常自吐蛔，手足厥冷，脉弦。","variants":["肚子一阵阵绞着痛，吐得厉害，有时还吐出虫子，手脚发凉。","一吃东西就犯呕，肚子痛得打滚，手脚冰冷的。","心口闹腾想吐，腹痛时作时止，人虚得手脚厥冷。"],"differentials":["理中汤","大建中汤"],"difficulty":"难点","tags":["腹痛","呕吐","蛔厥","手足厥冷","寒热错杂"]},{"id":"F030","no":30,"name":"栀子豉汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，烦躁","composition":[{"herb":"栀子","gram":9,"processing":""},{"herb":"淡豆豉","gram":9,"processing":""}],"pathogenesis":"汗吐下后余热留扰胸膈，郁热不宣，心神不宁。","standardSymptom":"心中懊憹，烦不得眠，胸中窒闷，按之心下软，舌红苔微黄，脉数。","variants":["心里头像有团火堵着，烦得睡不着，胸口闷闷的透不过气。","折腾完之后心里总是不踏实，坐也不是站也不是，躺下更烦。","胸口感觉闷着一团热气，说不出的难受，舌头有点红苔还发黄。"],"differentials":["白虎汤","栀子厚朴汤"],"difficulty":"进阶","tags":["心烦","失眠","胸窒","懊憹","舌红"]},{"id":"F031","no":31,"name":"栀子厚朴汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，腹胀","composition":[{"herb":"栀子","gram":9,"processing":""},{"herb":"厚朴","gram":9,"processing":""},{"herb":"枳实","gram":9,"processing":""}],"pathogenesis":"热邪内陷，气机壅滞于腹，心烦腹满，卧起不安。","standardSymptom":"心烦腹满，卧起不安，腹胀按之柔软，舌红苔黄，脉数。","variants":["肚子里胀得慌，心里还烦，躺下不行起来也不行，坐立难安。","吃了东西肚子就鼓胀，心里毛毛的，翻来覆去睡不踏实。","小腹闷胀顶着，人烦躁得很，怎么待着都不舒服。"],"differentials":["栀子豉汤","大承气汤"],"difficulty":"进阶","tags":["腹胀","心烦","卧起不安","苔黄"]},{"id":"F032","no":32,"name":"麻子仁丸","alias":["脾约丸"],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，便秘","composition":[{"herb":"麻子仁","gram":20,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"枳实","gram":9,"processing":""},{"herb":"大黄","gram":6,"processing":""},{"herb":"厚朴","gram":9,"processing":""},{"herb":"杏仁","gram":9,"processing":""}],"pathogenesis":"胃中燥热，脾约津亏，肠失濡润，大便硬结。","standardSymptom":"大便秘结，小便频数，脘腹痞满，舌红苔黄燥，脉滑数。","variants":["好几天上不了厕所，屎又干又硬，可尿还特别频，肚子胀。","上厕所费劲得很，便便一粒一粒的像羊粪蛋，还老跑厕所小便。","大便干结拉不出，肚子隐隐发堵，水喝不少小便却多。"],"differentials":["大承气汤","六味地黄丸"],"difficulty":"进阶","tags":["便秘","小便频数","腹胀","苔燥"]},{"id":"F033","no":33,"name":"黄芩汤","alias":["黄芩芍药汤"],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，腹泻","composition":[{"herb":"黄芩","gram":9,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"阳明湿热下注，邪迫大肠，气血不和，下利腹痛。","standardSymptom":"下利腹痛，肛门灼热，口苦咽干，舌红苔黄，脉弦数。","variants":["拉肚子还肚子绞着痛，屁股火辣辣的，嘴里发苦喉咙干。","一天跑好几趟厕所，便便黏臭，肚子隐隐作痛，舌苔发黄。","肠胃闹得慌，又拉又痛，口苦得厉害，舌头红红的。"],"differentials":["葛根芩连汤","白头翁汤"],"difficulty":"进阶","tags":["下利","腹痛","肛门灼热","口苦"]},{"id":"F034","no":34,"name":"旋复花代赭石汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，嗳气","composition":[{"herb":"旋复花","gram":9,"processing":""},{"herb":"代赭石","gram":3,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"胃虚痰阻，气逆不降，噫气不除，心下痞硬。","standardSymptom":"心下痞硬，嗳气频作，呃逆不止，纳差，舌淡苔白，脉弦。","variants":["老是不停地打嗝，胃里堵得慌，吃一点就顶在胸口下不去。","嗳气打个没完，按着心口下边硬邦邦的，饭也吃不下。","胃气老往上翻，呃逆声连连，胸口下闷堵，没胃口。"],"differentials":["半夏泻心汤","橘皮竹茹汤"],"difficulty":"难点","tags":["嗳气","呃逆","心下痞","纳差"]},{"id":"F035","no":35,"name":"小陷胸汤","alias":[],"source":"伤寒论","meridians":["阳明","少阳"],"subPattern":"阳明热象，胸中痛","composition":[{"herb":"黄连","gram":6,"processing":""},{"herb":"半夏","gram":12,"processing":""},{"herb":"瓜蒌实","gram":20,"processing":""}],"pathogenesis":"痰热互结于心下胸膈，气机不通，则胸脘痞痛。","standardSymptom":"胸脘痞闷作痛，按之则痛，咳痰黄稠，舌红苔黄腻，脉滑数。","variants":["胸口到胃这块闷痛，一按更疼，吐的痰又黄又黏。","心口窝那儿堵着痛，按下疼得厉害，痰黄稠糊糊的。","前胸胃脘又闷又痛，摸上去有压痛，痰黄腻，舌头苔厚。"],"differentials":["大陷胸汤","半夏泻心汤"],"difficulty":"难点","tags":["胸脘痛","按之痛","黄痰","苔腻"]},{"id":"F036","no":36,"name":"大陷胸汤","alias":[],"source":"伤寒论","meridians":["阳明"],"subPattern":"阳明热象，胸痛硬满","composition":[{"herb":"大黄","gram":10,"processing":""},{"herb":"芒硝","gram":10,"processing":""},{"herb":"甘遂","gram":1,"processing":"研末冲服"}],"pathogenesis":"水热互结于胸腹，气机壅塞，心下硬满剧痛。","standardSymptom":"心下硬满疼痛，不可近手，潮热便秘，舌红苔黄燥，脉沉紧。","variants":["肚子上方硬邦邦地剧痛，碰都不敢碰，还发潮热拉不出屎。","胸口胃脘硬满得像石头，疼得直不起腰，大便干结。","上腹硬痛拒按，身上一阵阵发热，便秘，舌苔焦黄。"],"differentials":["小陷胸汤","大承气汤"],"difficulty":"难点","tags":["硬满","剧痛","拒按","潮热","便秘"]},{"id":"F037","no":37,"name":"小柴胡汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳原证","composition":[{"herb":"柴胡","gram":24,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"邪犯少阳，枢机不利，正邪分争，胆胃不和。","standardSymptom":"往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，口苦咽干目眩，脉弦。","variants":["一阵冷一阵热，两边肋骨胀闷，不想吃饭，心里烦还老想吐。","忽冷忽热像打摆子，口苦咽干，胸口两侧堵得慌，犯恶心。","寒热来回折腾，胁下胀满没胃口，头晕眼花嘴里发苦。"],"differentials":["大柴胡汤","桂枝汤"],"difficulty":"入门","tags":["往来寒热","胸胁苦满","口苦","喜呕","脉弦"]},{"id":"F038","no":38,"name":"柴胡加龙骨牡蛎汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳，惊恐不安","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"黄芩","gram":6,"processing":""},{"herb":"生姜","gram":6,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"桂枝","gram":6,"processing":""},{"herb":"茯苓","gram":6,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"大黄","gram":6,"processing":""},{"herb":"龙骨","gram":6,"processing":""},{"herb":"牡蛎","gram":6,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"少阳不和，肝胆郁热，心神被扰，惊狂不安。","standardSymptom":"胸满烦惊，小便不利，谵语，一身尽重，难以转侧，舌红苔黄，脉弦数。","variants":["心里总发慌易受惊，胸口闷，晚上糊里糊涂说胡话，身子沉。","动不动就吓一跳，烦躁睡不安，小便不顺，浑身沉重转侧难。","受了惊吓后心神不宁，胸闷烦躁，迷迷糊糊说些莫名其妙的话。"],"differentials":["桂枝甘草龙骨牡蛎汤","柴胡疏肝散"],"difficulty":"进阶","tags":["烦惊","谵语","胸满","身重","脉弦数"]},{"id":"F039","no":39,"name":"柴胡加芒硝汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳，潮热微利","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"黄芩","gram":6,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"生姜","gram":6,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""},{"herb":"芒硝","gram":6,"processing":"冲服"}],"pathogenesis":"少阳未解，兼阳明燥结，误下后热结旁流，故见潮热微利。","standardSymptom":"胸胁满而呕，日晡潮热，微利，舌暗红苔黄，脉弦。","variants":["两边胁下胀，老犯恶心，每到傍晚就潮热，还一直有点拉肚子（热利）。","胸口两侧闷胀想吐，午后一阵潮热，误下之后仍微微腹泻。","少阳病没好利索，又添了潮热，胁满呕逆，却下利不止（热结旁流）。"],"differentials":["大柴胡汤","小柴胡汤"],"difficulty":"进阶","tags":["胸胁满","呕","潮热","微利"]},{"id":"F040","no":40,"name":"柴胡去黄芩加半夏生姜汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳，呕吐","composition":[{"herb":"柴胡","gram":24,"processing":""},{"herb":"半夏","gram":15,"processing":""},{"herb":"生姜","gram":15,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"少阳不和兼胃寒饮停，胃气上逆，呕吐频作。","standardSymptom":"胸胁胀闷，呕吐清水，不欲饮食，舌淡苔白，脉弦。","variants":["两边肋骨发胀，一个劲地吐清水，吃啥都没胃口。","胃里翻江倒海直吐清涎，胁下闷胀，人没精神不想吃。","恶心吐个不停，吐出来的都是清水，胸胁堵着，舌苔白。"],"differentials":["小半夏汤","吴茱萸汤"],"difficulty":"难点","tags":["呕吐","清水","胸胁胀","不欲食"]},{"id":"F041","no":41,"name":"小柴胡汤去黄芩加夏","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳，咳嗽","composition":[{"herb":"柴胡","gram":24,"processing":""},{"herb":"半夏","gram":15,"processing":""},{"herb":"生姜","gram":15,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"少阳不和，胃虚痰饮，肺气上逆，咳而呕逆。","standardSymptom":"咳嗽痰多，胸胁不适，恶心呕吐，舌淡红苔白，脉弦。","variants":["咳嗽老不好，痰特多，还一阵阵犯恶心，两边肋下不舒坦。","一咳就吐，痰涎不少，胸口胁下闷胀，人没力气。","咳声连连痰往上涌，伴着恶心，胁部隐隐发堵。"],"differentials":["小青龙汤","二陈汤"],"difficulty":"难点","tags":["咳嗽","痰多","呕逆","胸胁不适"]},{"id":"F042","no":42,"name":"大柴胡汤","alias":[],"source":"伤寒论","meridians":["少阳","阳明"],"subPattern":"少阳阳明合病","composition":[{"herb":"柴胡","gram":24,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"生姜","gram":15,"processing":""},{"herb":"枳实","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""},{"herb":"大黄","gram":6,"processing":""}],"pathogenesis":"少阳未解，兼入阳明，腑气不通，实热内结。","standardSymptom":"往来寒热，胸胁苦满，心下急痛，大便秘结，舌红苔黄，脉弦数。","variants":["冷热交替，胁下胀满，心口窝急痛，好几天拉不出屎。","忽冷忽热，胸口两侧憋闷，上腹绞痛，便秘苔黄。","少阳证没解，又添了腑实，心下硬痛拒按，大便干结。"],"differentials":["小柴胡汤","大承气汤"],"difficulty":"进阶","tags":["往来寒热","胸胁满","心下急","便秘"]},{"id":"F043","no":43,"name":"少阳百合汤","alias":[],"source":"金匮要略","meridians":["少阳"],"subPattern":"少阳热象，情志不宁","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"百合","gram":30,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"生地","gram":15,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"少阳郁热，心神失养，情志不宁，百脉不和。","standardSymptom":"神情默默，心烦不安，口苦口干，眠差，舌红苔薄黄，脉弦细。","variants":["心里总不踏实，说不出的烦，嘴里干苦，晚上翻来覆去睡不着。","人蔫蔫的不想说话，情绪忽上忽下，睡不踏实，舌头偏红。","总觉着心里发躁，口干苦，神情恍惚睡不安稳。"],"differentials":["百合地黄汤","小柴胡汤"],"difficulty":"难点","tags":["情志不宁","心烦","失眠","口苦","脉弦细"]},{"id":"F044","no":44,"name":"竹叶石膏汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳热象，虚热","composition":[{"herb":"竹叶","gram":9,"processing":""},{"herb":"石膏","gram":30,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"麦冬","gram":15,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"粳米","gram":10,"processing":""}],"pathogenesis":"少阳余热未清，气阴两伤，虚热上扰，胃气不和。","standardSymptom":"低热不退，心烦口渴，气短神疲，干呕少食，舌红少苔，脉虚数。","variants":["身上老有股低热退不净，咽干想喝水，干呕吃不下，人乏得很。","病后虚热反复，嘴里干渴，胃里往上顶，没力气精神差。","低烧绵绵不去，喉咙干，少食易呕，舌红少苔人软塌。"],"differentials":["小柴胡汤","白虎汤"],"difficulty":"进阶","tags":["低热","口渴","干呕","气短","舌红少苔"]},{"id":"F045","no":45,"name":"黄芩汤","alias":["黄芩芍药汤"],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳热象，腹泻","composition":[{"herb":"黄芩","gram":9,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"少阳郁热下迫大肠，肝脾不和，下利腹痛。","standardSymptom":"腹痛下利，便稀色黄，心烦口苦，脉弦数，舌红苔黄。","variants":["肚子一阵阵绞痛就泻，便稀发黄，心里烦躁嘴里苦。","拉肚子伴腹痛，屎色偏黄稀溏，胁下不舒，脉弦。","肠鸣腹痛就往厕所跑，便黄而臭，口苦心烦。"],"differentials":["痛泻要方","葛根芩连汤"],"difficulty":"进阶","tags":["下利","腹痛","口苦","脉弦数"]},{"id":"F046","no":46,"name":"半夏泻心汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳热象，寒热错杂痞","composition":[{"herb":"半夏","gram":12,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":""},{"herb":"黄连","gram":3,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"少阳误下，寒热错杂，中焦痞塞，升降失司。","standardSymptom":"心下痞满不痛，呕吐肠鸣，下利，舌淡红苔腻，脉弦。","variants":["心口下堵得慌却不觉痛，又吐又泻，肚子里咕咕响。","胃脘痞闷像压了块石头，嗳气肠鸣，上吐下泻。","中焦堵闷不舒，呕恶便溏，肠鸣辘辘，舌苔腻。"],"differentials":["生姜泻心汤","甘草泻心汤"],"difficulty":"进阶","tags":["心下痞","呕吐","肠鸣","下利"]},{"id":"F047","no":47,"name":"生姜泻心汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳热象，水热互结","composition":[{"herb":"生姜","gram":12,"processing":""},{"herb":"甘草","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"干姜","gram":3,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"黄连","gram":3,"processing":""},{"herb":"大枣","gram":4,"processing":""}],"pathogenesis":"水热互结，胃虚不化，水气内停，升降失常。脾虚水停，食谷不消，故干噫食臭、腹中雷鸣。","standardSymptom":"干噫食臭，心下痞硬，腹中雷鸣，下利，舌淡苔腻，脉弦。","variants":["老嗳气带股酸馊的食臭味，心下痞硬，肚子咕咕响。","胃里泛气不消化，嗳气有宿食味，肠鸣便溏。","干噫不止带食臭，心口下堵硬，腹中雷鸣下利。"],"differentials":["半夏泻心汤","甘草泻心汤"],"difficulty":"难点","tags":["干噫食臭","心下痞","肠鸣","下利"]},{"id":"F048","no":48,"name":"甘草泻心汤","alias":[],"source":"伤寒论","meridians":["少阳"],"subPattern":"少阳热象，胃虚痞利","composition":[{"herb":"甘草","gram":12,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"大枣","gram":4,"processing":""},{"herb":"黄连","gram":3,"processing":""},{"herb":"人参","gram":9,"processing":""}],"pathogenesis":"胃气重虚，寒热错杂，客气上逆，腹鸣下利。","standardSymptom":"腹中雷鸣，下利日数十行，完谷不化，心下痞硬而满，干呕心烦，舌淡苔腻，脉濡弱。","variants":["肚子里响得像打雷，一天拉好多次还完谷不化，心下痞满干呕心烦。","肠鸣如雷，泄泻频数，胃脘堵满，干呕心里烦，屎里夹不消化食物。","肚子咕噜不止，水泻不停，心下硬满，干哕不安，完谷不化。"],"differentials":["半夏泻心汤","生姜泻心汤"],"difficulty":"难点","tags":["腹鸣","下利","完谷不化","心下痞","干呕"]},{"id":"F049","no":49,"name":"理中汤","alias":["人参汤"],"source":"伤寒论","meridians":["太阴"],"subPattern":"太阴脾阳虚","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":""}],"pathogenesis":"太阴脾阳虚弱，寒湿内停，运化失司，升降失常。","standardSymptom":"腹痛喜温喜按，呕吐泄泻，畏寒肢冷，舌淡苔白，脉沉细。","variants":["肚子疼得喜欢捂热水袋，又吐又泻，手脚冰凉怕冷。","胃脘冷痛，按着舒服，拉肚子，整个人畏寒没精神。","吃凉的就泻，腹中隐痛喜暖，四肢发冷，舌苔白。"],"differentials":["四君子汤","附子理中汤"],"difficulty":"入门","tags":["腹痛喜温","呕吐","泄泻","畏寒","舌淡"]},{"id":"F050","no":50,"name":"附子理中汤","alias":[],"source":"伤寒论","meridians":["太阴"],"subPattern":"太阴脾阳虚，阳虚重","composition":[{"herb":"附子","gram":9,"processing":"先煎"},{"herb":"干姜","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":""}],"pathogenesis":"脾阳虚极及肾，阴寒内盛，温运无力，肢冷厥逆。","standardSymptom":"脘腹冷痛剧烈，下利清谷，四肢厥冷，舌淡胖苔白滑，脉沉微。","variants":["肚子冷痛得厉害，拉的全是没消化的，手脚冰到胳膊肘。","胃腹剧痛怕冷，泻下水样便，四肢厥冷，脉都快摸不着。","阳虚得重，脘腹寒痛喜暖，下利清谷，全身怕冷。"],"differentials":["理中汤","四逆汤"],"difficulty":"进阶","tags":["冷痛","下利清谷","肢厥","畏寒重","脉沉微"]},{"id":"F051","no":51,"name":"大建中汤","alias":[],"source":"金匮要略","meridians":["太阴"],"subPattern":"太阴脾阳虚，腹中冷痛","composition":[{"herb":"蜀椒","gram":6,"processing":"炒去汗"},{"herb":"干姜","gram":12,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"饴糖","gram":30,"processing":""}],"pathogenesis":"中阳衰微，阴寒内盛，寒凝气滞，腹中剧痛。","standardSymptom":"心胸中大寒痛，呕不能食，腹中寒、上冲皮起（出见有头足），上下痛而不可触近，手足厥冷，舌淡苔白滑，脉沉伏或迟。","variants":["肚子疼得在床上打滚，手按上去更疼，还吐得吃不下饭。","肚子里面像有冰块，一阵阵绞着痛，手脚都冰凉。","胸口到肚子都痛得慌，稍微碰一下就受不了，还直犯恶心。"],"differentials":["小建中汤"],"difficulty":"难点","tags":["腹中冷痛","手足厥冷","呕不能食","舌淡苔白"]},{"id":"F052","no":52,"name":"小建中汤","alias":[],"source":"伤寒论","meridians":["太阴"],"subPattern":"太阴脾虚，虚劳","composition":[{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":18,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"甘草","gram":6,"processing":""},{"herb":"饴糖","gram":30,"processing":""}],"pathogenesis":"中焦虚寒，肝脾不和，里急腹痛，虚劳心悸","standardSymptom":"腹中拘急疼痛，喜温喜按，心悸虚烦，梦遗失精，手足烦热，咽干口燥，舌淡红苔薄白，脉弦细。","variants":["肚子一阵阵抽着疼，揉一揉、捂个热水袋就舒服点。","人瘦得厉害，身上一阵冷一阵热，心里老是慌。","胃里隐隐作痛，吃点凉的就犯，还总睡不踏实。"],"differentials":["大建中汤","桂枝加芍药汤"],"difficulty":"进阶","tags":["腹中拘急","喜温喜按","心悸","虚劳","脉弦细"]},{"id":"F053","no":53,"name":"黄芪建中汤","alias":[],"source":"小儿药证直诀","meridians":["太阴"],"subPattern":"太阴脾虚，虚劳里急，气不摄血","composition":[{"herb":"黄芪","gram":9,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":18,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"甘草","gram":6,"processing":""},{"herb":"饴糖","gram":30,"processing":""}],"pathogenesis":"中气虚寒较甚，阴阳气血俱不足，里急腹痛","standardSymptom":"虚劳里急，诸不足，腹中时时拘痛，喜温喜按，神疲乏力，短气自汗，面色萎黄，舌淡苔薄，脉虚弱。","variants":["干啥都提不起劲，稍微动动就出一身虚汗，肚子还老抽痛。","人特别虚，吃不下又瘦得快，肚子里隐隐作痛。","气短得慌，脸色蜡黄，肚子一阵阵发紧疼。"],"differentials":["小建中汤","当归建中汤","归脾汤"],"difficulty":"难点","tags":["虚劳","自汗","乏力","腹中拘痛","脉虚"]},{"id":"F054","no":54,"name":"四君子汤","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴气虚","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""}],"pathogenesis":"脾胃气虚，运化乏力，气血生化不足","standardSymptom":"面色萎白，语声低微，气短乏力，食少便溏，舌淡苔白，脉细弱。","variants":["吃饭没胃口，吃完肚子胀，人没精神，大便还稀。","总觉得浑身没力气，说话声音小，脸色白白的。","脾胃虚弱，吃点东西就不消化，人瘦巴巴的。"],"differentials":["补中益气汤","六君子汤","理中丸"],"difficulty":"入门","tags":["食少","便溏","气短","乏力","舌淡脉细"]},{"id":"F055","no":55,"name":"六君子汤","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴气虚，痰湿","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"陈皮","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""}],"pathogenesis":"脾胃气虚，运化乏力，痰湿内生，气滞中焦","standardSymptom":"食少便溏，胸脘痞闷，呕恶痰多，神疲乏力，舌淡苔白腻，脉虚滑。","variants":["胃里老是胀乎乎的，还反酸想吐，痰特别多。","吃不下饭，胸口堵得慌，一咳就吐白痰。","脾胃弱又痰湿重，人困得慌，舌头上一层白腻苔。"],"differentials":["四君子汤","香砂六君子汤","二陈汤"],"difficulty":"进阶","tags":["脘痞","呕吐","痰多","便溏","苔白腻"]},{"id":"F056","no":56,"name":"四君子加陈皮半夏","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴气虚，痰湿","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"陈皮","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""}],"pathogenesis":"气虚夹痰，胃气上逆，侧重呕恶痞满","standardSymptom":"胃气不和，恶心呕吐明显，脘腹胀满，食入难化，舌淡胖苔白腻，脉滑。","variants":["一吃东西就往上反，胃里胀得坐不住。","老觉得胃里堵着，恶心想吐，还嗳气。","肚子胀还吐清水，嗓子眼里痰鸣辘辘的。"],"differentials":["六君子汤","四君子汤"],"difficulty":"进阶","tags":["恶心","脘胀","呕吐","痰阻"]},{"id":"F057","no":57,"name":"健脾生血汤","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴脾虚，血虚","composition":[{"herb":"党参","gram":15,"processing":""},{"herb":"白术","gram":10,"processing":""},{"herb":"茯苓","gram":10,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"黄芪","gram":15,"processing":""},{"herb":"当归","gram":10,"processing":""},{"herb":"白芍","gram":10,"processing":""},{"herb":"山药","gram":15,"processing":""},{"herb":"陈皮","gram":6,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"}],"pathogenesis":"脾虚失运，气血双亏，心神失养","standardSymptom":"面色萎黄或㿠白，食欲不振，乏力头晕，心悸失眠，爪甲色淡，舌淡苔薄，脉细弱。","variants":["脸色蜡黄没血色，蹲下起来就头晕眼花。","吃饭不香，人虚得慌，心跳老快，睡不好。","指甲发白，浑身没劲，记性也差了。"],"differentials":["归脾汤","四君子汤"],"difficulty":"难点","tags":["面色萎黄","头晕","心悸","血虚","乏力"]},{"id":"F058","no":58,"name":"补中益气汤","alias":[],"source":"脾胃论","meridians":["太阴"],"subPattern":"太阴脾虚气陷，清阳不升","composition":[{"herb":"黄芪","gram":18,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"陈皮","gram":6,"processing":""},{"herb":"升麻","gram":6,"processing":""},{"herb":"柴胡","gram":6,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"当归","gram":9,"processing":""}],"pathogenesis":"脾胃气虚，清阳下陷，中气不足，摄纳无权","standardSymptom":"饮食减少，体倦肢软，少气懒言，面色萎黄，大便稀溏，舌淡脉虚；或脱肛、子宫脱垂、久泻久痢、崩漏；或身热自汗，渴喜热饮，气短乏力，舌淡，脉虚大无力。","variants":["人老是犯困没力气，吃一点就肚子胀，还脱肛，少气懒言。","气短懒得说话，下腹坠胀，大便总拉不干净，站久了往下坠。","一阵阵发热出汗，渴了爱喝热水，人虚得很，脉摸上去又大又空。"],"differentials":["四君子汤","归脾汤","升陷汤"],"difficulty":"进阶","tags":["气陷","脱肛","脏器下垂","乏力","气虚发热","自汗"]},{"id":"F059","no":59,"name":"四君子汤加减","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴气虚各证","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"陈皮","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"木香","gram":6,"processing":""},{"herb":"砂仁","gram":6,"processing":""}],"pathogenesis":"气虚为本，随证加减，或化痰或理气或温中","standardSymptom":"脾胃气虚兼见脘腹胀满、呕恶或便溏，随兼证不同而症状互显，舌淡苔白，脉虚弱。","variants":["脾胃虚还胀气，加点陈皮木香就顺气多了。","气虚又吐痰，配上半夏陈皮才管用。","我脾胃差，大夫说在四君子底子上随症调几味。"],"differentials":["四君子汤","六君子汤"],"difficulty":"进阶","tags":["气虚","随证加减","脘胀","便溏"]},{"id":"F060","no":60,"name":"参苓白术散","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴脾虚，湿困","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"山药","gram":15,"processing":""},{"herb":"莲子","gram":9,"processing":""},{"herb":"薏苡仁","gram":15,"processing":""},{"herb":"砂仁","gram":6,"processing":""},{"herb":"桔梗","gram":6,"processing":""},{"herb":"白扁豆","gram":12,"processing":""}],"pathogenesis":"脾虚湿盛，运化失司，大便溏泄","standardSymptom":"食少便溏，形体消瘦，胸脘痞闷，肠鸣泄泻，四肢乏力，舌淡苔白腻，脉细缓。","variants":["大便一天好几回还稀，人瘦了，腿也没劲。","肠胃弱，吃点油腻就拉肚子，肚子里咕噜响。","身子困重没力气，吃饭不香还老拉肚子。"],"differentials":["四君子汤","补中益气汤"],"difficulty":"进阶","tags":["便溏","泄泻","乏力","纳差","苔白腻"]},{"id":"F061","no":61,"name":"保脾煎","alias":[],"source":"医学启源","meridians":["太阴"],"subPattern":"太阴脾虚，腹泻","composition":[{"herb":"白术","gram":12,"processing":""},{"herb":"茯苓","gram":12,"processing":""},{"herb":"山药","gram":15,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"陈皮","gram":9,"processing":""},{"herb":"砂仁","gram":6,"processing":""},{"herb":"薏苡仁","gram":15,"processing":""},{"herb":"白扁豆","gram":12,"processing":""}],"pathogenesis":"脾虚失运，湿浊下注，久泻不止","standardSymptom":"久泻不愈，大便溏薄，食少神疲，腹胀肠鸣，舌淡苔白，脉缓弱。","variants":["拉肚子拉了半个月，吃的少也没精神。","肚子老咕噜响，一吃凉的就泻，人虚得慌。","慢性腹泻，大便稀溏，人瘦得脱了形。"],"differentials":["参苓白术散","四神丸"],"difficulty":"难点","tags":["久泻","便溏","肠鸣","纳差"]},{"id":"F062","no":62,"name":"四逆汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴心肾阳衰，寒厥","composition":[{"herb":"附子","gram":15,"processing":"先煎"},{"herb":"干姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""}],"pathogenesis":"少阴心肾阳衰，阴寒内盛，阳气不达四末，厥逆危候","standardSymptom":"四肢厥逆，恶寒蜷卧，神衰欲寐，面色苍白，腹痛下利，呕吐不渴，舌苔白滑，脉微细。","variants":["手脚冰凉透骨，裹多厚都暖不回来，人萎靡得只想蜷着睡觉。","拉肚子全是没消化的食物渣，浑身怕冷缩成一团，脸色惨白。","脉都快摸不着了，手脚冰冷，精神恍惚，老想闭眼。"],"differentials":["通脉四逆汤","四逆加人参汤","白通汤"],"difficulty":"入门","tags":["四肢厥逆","恶寒蜷卧","下利清谷","脉微细","神衰欲寐"]},{"id":"F063","no":63,"name":"回阳救急汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴阳虚，急症","composition":[{"herb":"熟附子","gram":12,"processing":"先煎"},{"herb":"干姜","gram":9,"processing":""},{"herb":"肉桂","gram":6,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"陈皮","gram":6,"processing":""},{"herb":"半夏","gram":9,"processing":""},{"herb":"五味子","gram":6,"processing":""},{"herb":"麝香","gram":0.1,"processing":"冲服"}],"pathogenesis":"少阴阳衰，寒邪直中，气血欲脱之危候","standardSymptom":"四肢厥冷，恶寒蜷卧，神昏不醒，冷汗淋漓，脉微欲绝，或见呕吐泄泻。","variants":["人昏迷不醒，冷汗直冒，手脚冰得吓人。","阳气要脱了，脉都快没了，急得要回阳救逆。","寒毒直中，人事不省，浑身冷汗淋漓。"],"differentials":["四逆汤","回阳救逆汤"],"difficulty":"难点","tags":["肢厥","神昏","冷汗","脉微欲绝"]},{"id":"F064","no":64,"name":"吴茱萸汤","alias":[],"source":"伤寒论","meridians":["厥阴","阳明","少阴"],"subPattern":"厥阴肝胃虚寒，浊阴上逆","composition":[{"herb":"吴茱萸","gram":9,"processing":""},{"herb":"人参","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":"擘"},{"herb":"生姜","gram":18,"processing":""}],"pathogenesis":"肝胃虚寒，浊阴上逆，胃失和降，气逆冲胸。","standardSymptom":"食后泛泛欲吐，或呕吐酸水，或干呕，或吐清涎冷沫，胸满脘痛，巅顶头痛，畏寒肢冷，烦躁欲死，舌淡苔白滑，脉沉弦或迟。","variants":["胃里一阵阵冷痛，吐的都是清口水，头顶疼得要命，烦得想撞墙。","吃完东西就往上反，干呕吐清稀口水，巅顶痛连脑仁。","胃寒吐涎沫，头顶像被冰水浇，烦得坐立不安。"],"differentials":["四逆汤","理中汤"],"difficulty":"进阶","tags":["胃寒痛","吐清涎","巅顶痛","畏寒","烦躁欲死"]},{"id":"F065","no":65,"name":"黄连阿胶汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴阴虚火旺，心肾不交","composition":[{"herb":"黄连","gram":12,"processing":""},{"herb":"黄芩","gram":6,"processing":""},{"herb":"芍药","gram":6,"processing":""},{"herb":"阿胶","gram":9,"processing":"烊化"},{"herb":"鸡子黄","gram":2,"processing":"冲服"}],"pathogenesis":"少阴肾阴亏虚，心火亢盛，水火不济，心神不宁","standardSymptom":"心中烦，不得卧，口燥咽干，舌红苔少，脉细数。","variants":["心里烦躁得睡不着，口干舌燥，舌头发红。","翻来覆去失眠，手心脚心发热，心里烦。","阴虚火旺，夜里醒好几回，舌尖红得厉害。"],"differentials":["酸枣仁汤","栀子豉汤"],"difficulty":"进阶","tags":["心烦","不寐","舌红少苔","脉细数"]},{"id":"F066","no":66,"name":"麻黄细辛附子汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴阳虚，伤寒","composition":[{"herb":"麻黄","gram":6,"processing":""},{"herb":"细辛","gram":3,"processing":""},{"herb":"附子","gram":9,"processing":"先煎"}],"pathogenesis":"少阴阳虚，外感风寒，太少两感","standardSymptom":"恶寒发热，无汗，神疲乏力，脉沉微，虽发热而肢冷嗜卧。","variants":["感冒发烧却怕冷得厉害，人没精神想睡觉。","受了寒发低热，手脚凉，脉也沉得摸不清。","素来阳虚又伤风，无汗浑身紧，懒言嗜卧。"],"differentials":["桂枝加附子汤","麻黄附子甘草汤"],"difficulty":"难点","tags":["恶寒发热","无汗","脉沉","嗜卧"]},{"id":"F067","no":67,"name":"真武汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴脾肾阳虚，水气泛溢","composition":[{"herb":"茯苓","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"白术","gram":6,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"附子","gram":9,"processing":"先煎"}],"pathogenesis":"脾肾阳虚，水湿内停，水气凌心，泛溢肌肤","standardSymptom":"畏寒肢厥，小便不利，心下悸动不宁，头目眩晕，身体筋肉瞤动，站立不稳，四肢沉重疼痛，浮肿腰以下为甚，或腹痛泄泻，或咳喘呕逆，舌质淡胖边有齿痕，舌苔白滑，脉沉细。","variants":["腿脚浮肿按下去有坑，怕冷小便少，心里怦怦跳得慌，站起来晕晕乎乎。","阳虚水泛浑身肿，一动就喘，肚子隐痛拉肚子，舌胖大有齿印。","身上肌肉跳个不停，站都站不稳，腰以下肿得厉害。"],"differentials":["五苓散","苓桂术甘汤","附子汤"],"difficulty":"进阶","tags":["水肿","畏寒","心悸","小便不利","舌淡胖","身瞤动"]},{"id":"F068","no":68,"name":"白通汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴阳虚，下利","composition":[{"herb":"葱白","gram":12,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"附子","gram":15,"processing":"先煎"}],"pathogenesis":"少阴下利，阳衰阴盛，格阳于上","standardSymptom":"下利清谷，四肢厥逆，面色赤，恶寒脉微，或见干呕烦躁。","variants":["拉肚子全是没消化的食物，手脚冰，脸却发红。","下利肢厥，脉微欲绝，脸上泛着不正常的红。","寒盛下利，人冷得缩着，面赤如妆。"],"differentials":["四逆汤","白通加猪胆汁汤"],"difficulty":"进阶","tags":["下利","肢厥","面赤","脉微"]},{"id":"F069","no":69,"name":"白通加猪胆汁汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴阳虚，下利加重","composition":[{"herb":"葱白","gram":12,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"附子","gram":15,"processing":"先煎"},{"herb":"人尿","gram":30,"processing":""},{"herb":"猪胆汁","gram":10,"processing":""}],"pathogenesis":"少阴下利，阳衰阴盛，格拒加重，反佐为治","standardSymptom":"下利不止，厥逆无脉，干呕烦渴，服热药格拒，面赤，脉微欲绝。","variants":["拉肚子止不住，手脚冰脉都摸不到，吃药还往上呕。","重证阴盛格阳，干呕心烦，热药喂不进去。","下利厥逆无脉，面赤烦躁，非反佐不能纳。"],"differentials":["白通汤","四逆汤"],"difficulty":"难点","tags":["下利无脉","厥逆","干呕","格拒"]},{"id":"F070","no":70,"name":"干姜附子汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴阳虚，轻症","composition":[{"herb":"干姜","gram":9,"processing":""},{"herb":"附子","gram":15,"processing":"先煎"}],"pathogenesis":"少阴轻证，昼日烦躁，夜而安静，阳虚","standardSymptom":"昼日烦躁不得眠，夜而安静，身无大热，不呕不渴，脉沉微。","variants":["白天心里烦躁睡不着，一到夜里反倒安静了。","没发烧也不渴，就是白天躁得慌，脉又沉又弱。","阳虚烦躁，白天闹腾夜里安，身子虚冷。"],"differentials":["四逆汤","茯苓四逆汤"],"difficulty":"进阶","tags":["烦躁","昼躁夜静","脉沉微","阳虚"]},{"id":"F071","no":71,"name":"炙甘草汤","alias":[],"source":"伤寒论","meridians":["少阴"],"subPattern":"少阴心阴阳两虚，脉结代","composition":[{"herb":"甘草","gram":12,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"生地黄","gram":30,"processing":""},{"herb":"阿胶","gram":6,"processing":"烊化"},{"herb":"麦冬","gram":10,"processing":""},{"herb":"麻仁","gram":10,"processing":""},{"herb":"大枣","gram":10,"processing":"擘"}],"pathogenesis":"阴血阳气虚弱，心脉失养，脉气不相接续","standardSymptom":"脉结代，心动悸，虚羸少气，舌光少苔，或质干而瘦小。","variants":["心跳一阵快一阵慢还漏跳，胸口发闷，人瘦气短没力气。","心慌得厉害，脉搏时有停顿，舌头光红少苔，虚得不成样子。","心律不齐结代脉，心口悸动不安，身形羸瘦。"],"differentials":["天王补心丹","归脾汤","生脉散"],"difficulty":"进阶","tags":["心悸","脉结代","虚羸","气短","心动悸"]},{"id":"F072","no":72,"name":"酸枣仁汤","alias":[],"source":"金匮要略","meridians":["少阴"],"subPattern":"肝血不足，虚热内扰","composition":[{"herb":"酸枣仁","gram":15,"processing":"研"},{"herb":"茯苓","gram":9,"processing":""},{"herb":"知母","gram":9,"processing":""},{"herb":"川芎","gram":6,"processing":""},{"herb":"甘草","gram":3,"processing":""}],"pathogenesis":"肝血不足，阴虚内热，虚热扰神，心神不宁","standardSymptom":"虚烦失眠，心悸不安，头目眩晕，咽干口燥，舌红，脉弦细。","variants":["心里虚烦睡不着，老觉得心慌，头也晕乎乎，口干得厉害。","肝血不足的失眠，翻来覆去到半夜，舌头红红的脉又弦又细。","虚劳睡不着，烦得躺不住，咽干口燥，一闭眼就做梦。"],"differentials":["黄连阿胶汤","天王补心丹"],"difficulty":"进阶","tags":["虚烦失眠","心悸","眩晕","咽干","脉弦细"]},{"id":"F073","no":73,"name":"六味地黄丸","alias":[],"source":"医学启源","meridians":["少阴"],"subPattern":"少阴肾阴虚，虚火上炎","composition":[{"herb":"熟地黄","gram":24,"processing":""},{"herb":"山茱萸","gram":12,"processing":""},{"herb":"山药","gram":12,"processing":""},{"herb":"泽泻","gram":9,"processing":""},{"herb":"牡丹皮","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""}],"pathogenesis":"肾阴亏损，精髓不足，虚火上炎，阴虚内热","standardSymptom":"腰膝酸软，头晕目眩，耳鸣耳聋，盗汗遗精，骨蒸潮热，手足心热，口燥咽干，牙齿动摇，足跟作痛，舌红少苔，脉沉细数。","variants":["腰酸腿软没力气，头晕耳鸣，手心脚心热乎乎的，夜里还盗汗。","肾阴亏了，牙齿松动，足跟疼，口干咽燥，舌头红红的没什么苔。","骨子里发热像蒸笼，下午潮热，遗精盗汗，腰膝酸软。"],"differentials":["左归丸","知柏地黄丸"],"difficulty":"进阶","tags":["腰膝酸软","头晕耳鸣","盗汗","潮热","舌红少苔","牙齿动摇"]},{"id":"F074","no":74,"name":"左归丸","alias":[],"source":"医学启源","meridians":["少阴"],"subPattern":"少阴真阴不足，精髓亏损","composition":[{"herb":"熟地黄","gram":24,"processing":""},{"herb":"山药","gram":12,"processing":""},{"herb":"枸杞子","gram":12,"processing":""},{"herb":"山茱萸","gram":12,"processing":""},{"herb":"川牛膝","gram":9,"processing":""},{"herb":"菟丝子","gram":12,"processing":""},{"herb":"鹿胶","gram":12,"processing":"烊化"},{"herb":"龟胶","gram":12,"processing":"烊化"}],"pathogenesis":"真阴肾水不足，精髓内亏，纯虚无邪，纯补无泻","standardSymptom":"头晕目眩，腰酸腿软，遗精滑泄，自汗盗汗，口燥舌干，舌红少苔，脉细。","variants":["真阴亏极了，腰酸得直不起来，遗精频繁，头晕眼花站不稳。","精髓都不够了，整天晕乎乎的，自汗盗汗，口干舌燥。","记性差，腰膝痠软得厉害，舌头光红少苔，脉细得摸不着。"],"differentials":["六味地黄丸","右归丸","大补阴丸"],"difficulty":"难点","tags":["腰酸","遗精","自汗盗汗","口燥","真阴亏","头晕"]},{"id":"F075","no":75,"name":"滋阴至宝汤","alias":[],"source":"医学启源","meridians":["少阴"],"subPattern":"少阴阴虚热","composition":[{"herb":"当归","gram":9,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"陈皮","gram":9,"processing":""},{"herb":"柴胡","gram":6,"processing":""},{"herb":"知母","gram":9,"processing":""},{"herb":"贝母","gram":9,"processing":""},{"herb":"麦冬","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"薄荷","gram":3,"processing":""},{"herb":"生地黄","gram":12,"processing":""}],"pathogenesis":"少阴阴虚，肝郁化火，痰热骨蒸","standardSymptom":"骨蒸劳热，咳嗽痰少，午后潮热，心烦盗汗，咽干颊赤，舌红少苔，脉细数。","variants":["下午一阵阵发热，咳得少痰，心里烦躁。","骨蒸潮热，脸颊发红，盗汗，痰黏难咯。","阴虚肝郁，低热缠绵，咽干心烦睡不稳。"],"differentials":["六味地黄丸","清骨散"],"difficulty":"难点","tags":["骨蒸潮热","咳嗽","盗汗","咽干","脉细数"]},{"id":"F076","no":76,"name":"养心汤","alias":[],"source":"医学启源","meridians":["少阴"],"subPattern":"少阴气血不足，心神失养","composition":[{"herb":"黄芪","gram":12,"processing":"炙"},{"herb":"茯苓","gram":10,"processing":""},{"herb":"茯神","gram":10,"processing":""},{"herb":"当归","gram":10,"processing":""},{"herb":"川芎","gram":6,"processing":""},{"herb":"半夏曲","gram":10,"processing":""},{"herb":"柏子仁","gram":10,"processing":""},{"herb":"酸枣仁","gram":10,"processing":"炒"},{"herb":"远志","gram":6,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"肉桂","gram":3,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"五味子","gram":6,"processing":""}],"pathogenesis":"心脾两虚，气血不足，心神失养，兼心阴亦亏","standardSymptom":"心悸怔忡，健忘失眠，神疲乏力，面色少华，舌淡苔薄，脉细弱。","variants":["最近老是睡不着，心里空落落的，记性也差了，干点活就乏得不行。","大夫，我心跳忽快忽慢，晚上翻来覆去，白天一点精神都没有。","人没力气，睡不踏实，记不住事，舌头看着也淡淡的。"],"differentials":["酸枣仁汤","天王补心丹"],"difficulty":"进阶","tags":["心悸","失眠","健忘","神疲","乏力"]},{"id":"F077","no":77,"name":"安神汤","alias":[],"source":"医学启源","meridians":["少阴"],"subPattern":"少阴心虚，失眠","composition":[{"herb":"当归","gram":10,"processing":""},{"herb":"生地黄","gram":12,"processing":""},{"herb":"熟地黄","gram":12,"processing":""},{"herb":"茯神","gram":12,"processing":""},{"herb":"酸枣仁","gram":12,"processing":"炒"},{"herb":"莲子心","gram":3,"processing":""},{"herb":"远志","gram":6,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"}],"pathogenesis":"心阴亏虚，虚火内扰，神不内守，寤寐失常","standardSymptom":"心烦不寐，惊悸多梦，口燥咽干，舌红少苔，脉细数。","variants":["脑子里跟放电影似的，一闭眼全是事，心口还突突乱跳。","整宿整宿地醒，嘴干舌燥的，心里烦得慌。","睡觉轻得很，有点动静就惊，梦还多，舌头红得没津液。"],"differentials":["天王补心丹","黄连阿胶汤"],"difficulty":"难点","tags":["失眠","心烦","惊悸","口干","舌红"]},{"id":"F078","no":78,"name":"乌梅丸","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"厥阴蛔虫","composition":[{"herb":"乌梅","gram":30,"processing":""},{"herb":"细辛","gram":3,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"黄连","gram":9,"processing":""},{"herb":"当归","gram":6,"processing":""},{"herb":"附子","gram":6,"processing":"炮"},{"herb":"蜀椒","gram":6,"processing":"炒"},{"herb":"桂枝","gram":6,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"黄柏","gram":6,"processing":""}],"pathogenesis":"蛔厥寒热错杂，上热下寒，蛔虫内扰，气机逆乱","standardSymptom":"心烦呕吐，时发厥冷，腹痛时作，得食而呕，常自吐蛔，舌苔黄白相兼，脉沉弦。","variants":["肚子一阵阵地绞着疼，疼起来手脚都凉，还直犯恶心想吐。","我这毛病奇怪，一会儿怕冷一会儿烦热，吃口饭就往上顶。","小孩老说肚脐眼周围疼，疼得打滚，还吐过虫子。"],"differentials":["理中安蛔汤","大建中汤"],"difficulty":"进阶","tags":["腹痛","呕吐","厥冷","吐蛔","烦热"]},{"id":"F079","no":79,"name":"厥阴百合汤","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"厥阴热象","composition":[{"herb":"百合","gram":15,"processing":""},{"herb":"生地黄","gram":12,"processing":""},{"herb":"知母","gram":9,"processing":""},{"herb":"滑石","gram":9,"processing":"包煎"},{"herb":"甘草","gram":6,"processing":"炙"}],"pathogenesis":"厥阴郁热伤阴，虚热内蕴，神明被扰而不安","standardSymptom":"神情默默，欲卧不能卧，口苦微热，小便赤，舌红少津，脉细数。","variants":["说不出哪儿不舒服，就是心里发烦不想动，嘴里苦苦的。","整个人飘飘忽忽的，觉也睡不安，小便黄得厉害。","没精神也不想说话，摸着身上有点低热，舌头干红的。"],"differentials":["百合地黄汤","栀子豉汤"],"difficulty":"难点","tags":["心烦","默默","口苦","低热","尿赤"]},{"id":"F080","no":80,"name":"大承气汤","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"厥阴热象，腑实","composition":[{"herb":"大黄","gram":12,"processing":"后下"},{"herb":"厚朴","gram":15,"processing":""},{"herb":"枳实","gram":12,"processing":""},{"herb":"芒硝","gram":9,"processing":"冲服"}],"pathogenesis":"厥阴热盛，燥屎内结，腑气不通，热极而生厥","standardSymptom":"潮热谵语，腹胀满痛拒按，大便秘结，手足濈然汗出，或见手足厥冷（热深厥深），舌红苔黄燥，脉沉实有力。","variants":["好几天没解大便，肚子硬邦邦的疼，说胡话，身上一阵阵潮热。","肚子胀得像个鼓，碰都不敢碰，还净说些没影儿的话。","手脚心直冒汗，大便解不出，舌红苔焦黄，脉按着实硬的。"],"differentials":["小承气汤","调胃承气汤"],"difficulty":"进阶","tags":["便秘","腹胀痛","潮热","谵语","苔黄燥"]},{"id":"F081","no":81,"name":"当归四逆汤","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"血虚寒厥，经脉凝滞","composition":[{"herb":"当归","gram":12,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"细辛","gram":3,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"通草","gram":6,"processing":""},{"herb":"大枣","gram":12,"processing":""}],"pathogenesis":"营血虚弱，寒凝经脉，血行不利，阳气不达四末——其厥仅在指掌至腕踝，与亡阳之冷过肘膝有别","standardSymptom":"手足厥寒，指掌至腕踝不温，脉细欲绝，或腰股腿足肩臂疼痛，口不渴，舌淡苔白。","variants":["一到冬天手脚就冰得跟铁似的，指尖尤其凉，脉摸着细得快没了——身上倒不感觉冷得那么厉害。","我这腿脚老是发凉发麻，血脉好像不通，舌头颜色也淡——不是全身冷，就是末梢不温。","手指头冻得发紫，暖也暖不热，但腕肘之上还有温度，跟四逆汤那种全身厥冷不一样。"],"differentials":["四逆汤","黄芪桂枝五物汤"],"difficulty":"进阶","tags":["手足厥寒","脉细欲绝","肢麻","舌淡","血虚寒厥","肢端不温"]},{"id":"F082","no":82,"name":"当归四逆加吴茱萸生姜汤","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"血虚寒厥，内有久寒","composition":[{"herb":"当归","gram":12,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"细辛","gram":3,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"通草","gram":6,"processing":""},{"herb":"大枣","gram":12,"processing":""},{"herb":"吴茱萸","gram":9,"processing":""},{"herb":"生姜","gram":15,"processing":""}],"pathogenesis":"血虚寒凝更兼里有沉寒，厥阴肝寒犯胃，经脉凝滞，水饮内停","standardSymptom":"手足厥寒，脉细欲绝，内有久寒——或腹痛呕逆，或巅顶头痛，舌淡苔白滑，脉沉细迟。","variants":["手脚冰凉不算，肚子里也一阵阵冷痛，老想吐酸水——这是陈年老寒了。","常年小腹发凉抽着疼，暖水袋不离身，脑袋顶上还一阵阵疼，脉沉得几乎摸不到。","天稍冷就浑身寒颤，胃里泛清水，腰腹凉得像冰块，比单纯当归四逆汤多了个里寒。"],"differentials":["当归四逆汤","吴茱萸汤"],"difficulty":"难点","tags":["手足厥寒","脉细欲绝","腹痛","呕逆","内久寒","巅顶头痛","脉沉迟"]},{"id":"F083","no":83,"name":"桃红四物汤","alias":[],"source":"医学启源","meridians":["厥阴"],"subPattern":"肝血瘀滞，血虚夹瘀","composition":[{"herb":"桃仁","gram":9,"processing":""},{"herb":"红花","gram":6,"processing":""},{"herb":"当归","gram":12,"processing":""},{"herb":"川芎","gram":9,"processing":""},{"herb":"白芍","gram":12,"processing":""},{"herb":"熟地黄","gram":12,"processing":""}],"pathogenesis":"肝血不足，瘀血内阻——王绵之强调逐瘀类方须辨瘀之新久、血之盛衰，桃红四物汤是养血与活血并行的代表","standardSymptom":"面色晦暗或萎黄，唇甲色淡而青，局部刺痛固定不移，女子月经不调、经闭痛经或经色紫暗有块，舌淡紫或有瘀斑，脉细涩。","variants":["脸色暗而无华，嘴唇发乌发淡，身上老有一处一处地刺痛，位置还不变。","大姨妈好几个月没来，一来就疼得打滚，血色紫黑有血块，血量偏少。","舌头伸出来淡紫还有瘀斑，身上碰哪儿都青，脉摸着涩涩细细的。"],"differentials":["血府逐瘀汤","四物汤"],"difficulty":"进阶","tags":["刺痛","唇甲青紫或淡","经闭","痛经","舌淡紫","血虚血瘀","脉细涩"]},{"id":"F084","no":84,"name":"膈下逐瘀汤","alias":[],"source":"医学启源","meridians":["厥阴"],"subPattern":"膈下瘀血，气滞血瘀","composition":[{"herb":"五灵脂","gram":9,"processing":"炒"},{"herb":"当归","gram":9,"processing":""},{"herb":"川芎","gram":6,"processing":""},{"herb":"桃仁","gram":9,"processing":""},{"herb":"牡丹皮","gram":6,"processing":""},{"herb":"赤芍","gram":6,"processing":""},{"herb":"乌药","gram":6,"processing":""},{"herb":"延胡索","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":""},{"herb":"香附","gram":6,"processing":""},{"herb":"红花","gram":9,"processing":""},{"herb":"枳壳","gram":6,"processing":""}],"pathogenesis":"膈下瘀血内结，气机阻滞——王绵之指出逐瘀类方中膈下逐瘀汤专攻腹中瘀血，以痛处不移而拒按为辨证要点","standardSymptom":"腹中或胁下有痞块，刺痛拒按，痛处固定不移，或卧则腹坠似有物，舌暗有瘀斑，脉弦涩。","variants":["肚子右边老顶着个包块，按上去针扎似的疼，位置一动不动，越按越疼。","吃完饭肚子就铰着疼，摸着有硬结，躺下还感觉肚子里坠着东西，舌头乌青一片。","我这肚痛好些年了，疼起来不敢碰，脸色暗沉沉的，不是气胀是实打实的瘀块。"],"differentials":["少腹逐瘀汤","柴胡疏肝散"],"difficulty":"难点","tags":["腹痛","痞块","刺痛拒按","痛处固定","舌暗瘀斑","脉弦涩"]},{"id":"F085","no":85,"name":"逍遥散","alias":[],"source":"医学启源","meridians":["厥阴"],"subPattern":"肝郁血虚，脾弱不运","composition":[{"herb":"柴胡","gram":9,"processing":""},{"herb":"当归","gram":9,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"薄荷","gram":3,"processing":"后下"},{"herb":"生姜","gram":3,"processing":""}],"pathogenesis":"肝郁血虚，脾弱不运——王绵之指出逍遥散从三个环节调整脏腑功能：疏肝解郁、养血柔肝、健脾助运，三环相扣，以当归为第一君药、白芍为第二君药","standardSymptom":"两胁作痛，情志抑郁或烦躁，头痛目眩，口燥咽干，神疲食少，月经不调，乳房胀痛，舌淡红苔薄，脉弦而虚。","variants":["最近老爱生闷气，胸口和两肋胀得慌，吃不下饭人也没劲儿，月经也乱套了。","大姨妈乱了套，心情忽上忽下，胁肋胀满，嘴里干、没胃口，脉摸着弦弦的但底下虚。","啥事都提不起劲，胃胀嗳气，月经拖后，脸也没血色，容易着急上火又累得慌。"],"differentials":["柴胡疏肝散","四逆散","丹栀逍遥散"],"difficulty":"进阶","tags":["抑郁","胸胁胀","食少","月经不调","脉弦虚","肝郁血虚","脾弱"]},{"id":"F086","no":86,"name":"丹栀逍遥散","alias":[],"source":"医学启源","meridians":["厥阴"],"subPattern":"肝郁血虚，郁而化火","composition":[{"herb":"柴胡","gram":9,"processing":""},{"herb":"当归","gram":9,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"茯苓","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"薄荷","gram":3,"processing":"后下"},{"herb":"生姜","gram":3,"processing":""},{"herb":"牡丹皮","gram":9,"processing":""},{"herb":"栀子","gram":9,"processing":"炒"}],"pathogenesis":"肝郁日久化火，血虚脾弱未复，三焦郁热——王绵之谓丹栀逍遥散可清解三焦之郁火，是对逍遥散的重要发展","standardSymptom":"烦躁易怒，胸胁灼痛，口苦口干，头痛目赤，月经不调或经行先期量多色红，舌红苔薄黄，脉弦数。","variants":["火气一点就着，两胁烧得慌，嘴里发苦，月经提前色红量多，舌红舌苔黄。","心里烦躁睡不着，动不动发火，脸发红眼发赤，舌头红苔薄黄，脉跳得又快又硬。","明明郁着闷，又老上火长口疮，经水忽前忽后，心烦得坐不住——比逍遥散多了把火。"],"differentials":["逍遥散","龙胆泻肝汤"],"difficulty":"进阶","tags":["烦躁","易怒","口苦","胁痛","脉弦数","肝郁化火","三焦郁热"]},{"id":"F087","no":87,"name":"柴胡疏肝散","alias":[],"source":"医学启源","meridians":["厥阴"],"subPattern":"肝气郁滞，气滞血瘀","composition":[{"herb":"柴胡","gram":6,"processing":""},{"herb":"陈皮","gram":6,"processing":""},{"herb":"川芎","gram":6,"processing":""},{"herb":"香附","gram":6,"processing":""},{"herb":"枳壳","gram":6,"processing":""},{"herb":"白芍","gram":9,"processing":""},{"herb":"甘草","gram":3,"processing":""}],"pathogenesis":"肝气郁结，气滞血瘀——由四逆散加减而来，加陈皮、川芎、香附增强理气活血之力，专治胁肋胀痛","standardSymptom":"胁肋胀痛，走窜不定，胸闷善太息，情志不舒则甚，嗳气频作，脘腹胀满，舌淡红苔薄白，脉弦。","variants":["肋骨下头一阵阵窜着疼，生完气更厉害，老打嗝，胸闷得想长出气。","胸口堵得慌，气儿不顺，疼的地方还到处跑，嗳气连连才舒服点。","我这脾气一上来两边肋就胀疼，咕咕嗳气才舒服点，肚子也胀。"],"differentials":["逍遥散","四逆散"],"difficulty":"难点","tags":["胁肋胀痛","走窜","嗳气","情志不舒","脉弦","胸闷太息"]},{"id":"F088","no":88,"name":"四逆散","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"阳郁厥逆，肝脾气郁","composition":[{"herb":"柴胡","gram":9,"processing":""},{"herb":"枳实","gram":9,"processing":"炙"},{"herb":"芍药","gram":9,"processing":""},{"herb":"甘草","gram":9,"processing":"炙"}],"pathogenesis":"阳气内郁，不达四末，气机壅滞——王绵之强调四逆散之厥乃阳郁而非亡阳，手足不温但必不甚冷、指头微温、脉不沉微，与四逆汤之阴寒内盛、冷过肘膝、脉微欲绝有霄壤之别","standardSymptom":"手足不温（不甚冷，指头微温），或身微热，胸胁满闷，脘腹疼痛，或泄利下重，脉弦。","variants":["一生气着急手脚就发凉，可身上还一阵阵低热，胸口胁下闷胀——按着手不算冷，指头还有点温。","人看着不虚，可手足就是凉、按着不甚冷，胸胁闷胀，脉偏弦——不是四逆汤那种冰冷的。","一紧张就手脚发凉，肚子里咕噜咕噜，排便也不成形，后重感明显。"],"differentials":["四逆汤","当归四逆汤"],"difficulty":"进阶","tags":["手足不温","阳郁","胸胁满","腹痛","泄利","脉弦","指头微温"]},{"id":"F089","no":89,"name":"六磨汤","alias":[],"source":"医学启源","meridians":["厥阴"],"subPattern":"厥阴气滞，腹胀","composition":[{"herb":"沉香","gram":3,"processing":"后下"},{"herb":"木香","gram":6,"processing":""},{"herb":"槟榔","gram":9,"processing":""},{"herb":"乌药","gram":9,"processing":""},{"herb":"枳实","gram":9,"processing":""},{"herb":"大黄","gram":6,"processing":"后下"}],"pathogenesis":"气结于腹，腑气壅滞，七情气逆，腹胀便秘","standardSymptom":"腹胀满痛，便秘不行，欲便不得，嗳气食少，苔薄脉弦。","variants":["肚子胀得鼓鼓的，好几天不排便，憋得慌又解不出。","一着急上火就肚胀便秘，光打饱嗝吃不下。","我这腹胀跟情绪走，气不顺就堵着，脉弦得很。"],"differentials":["五磨饮子","大承气汤"],"difficulty":"难点","tags":["腹胀","便秘","嗳气","气逆","脉弦"]},{"id":"F090","no":90,"name":"复脉汤","alias":[],"source":"伤寒论","meridians":["厥阴"],"subPattern":"厥阴阴虚，心悸","composition":[{"herb":"炙甘草","gram":12,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"桂枝","gram":9,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"生地黄","gram":30,"processing":""},{"herb":"阿胶","gram":6,"processing":"烊化"},{"herb":"麦冬","gram":10,"processing":""},{"herb":"麻仁","gram":10,"processing":""},{"herb":"大枣","gram":12,"processing":""}],"pathogenesis":"阴血亏虚，心脉失养，阳气不振，心悸脉结","standardSymptom":"心悸心慌，脉结代，虚羸少气，舌光少苔，口干燥。","variants":["心跳老是漏一拍，人瘦得虚，嘴里干得慌，舌头光光的没苔。","心慌得厉害，脉时断时续，气儿短，浑身没肉。","胸口突突的，搭脉一会儿有一会儿没，舌头红得没津液。"],"differentials":["养心汤","生脉散"],"difficulty":"难点","tags":["心悸","脉结代","虚羸","口干","舌光"]},{"id":"F091","no":91,"name":"葛根汤","alias":[],"source":"伤寒论","meridians":["太阳","阳明"],"subPattern":"太阳阳明合病","composition":[{"herb":"葛根","gram":12,"processing":""},{"herb":"麻黄","gram":9,"processing":"先煎"},{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":""}],"pathogenesis":"太阳伤寒，阳明经气不舒，寒邪束表，经输不利","standardSymptom":"恶寒发热，无汗，项背强几几，下利或呕，苔薄白，脉浮紧。","variants":["脖子后头硬邦邦地僵，怕冷发烧不出汗，还窜稀。","后背连着脖子绷得紧，发高烧却不发汗，有点拉肚子。","受了寒浑身疼，后脑勺到肩背都板结，脉浮紧得很。"],"differentials":["桂枝加葛根汤","麻黄汤"],"difficulty":"进阶","tags":["项背强","恶寒","无汗","下利","脉浮紧"]},{"id":"F092","no":92,"name":"葛根加半夏汤","alias":[],"source":"伤寒论","meridians":["太阳","阳明"],"subPattern":"太阳阳明，呕吐","composition":[{"herb":"葛根","gram":12,"processing":""},{"herb":"麻黄","gram":9,"processing":"先煎"},{"herb":"桂枝","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"生姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":""},{"herb":"半夏","gram":9,"processing":"姜制"}],"pathogenesis":"太阳阳明合病，寒邪束表，里气上逆而作呕","standardSymptom":"恶寒发热，无汗项强，下利兼呕吐，苔白脉浮紧。","variants":["着了凉又拉又吐，后脖子僵硬，发烧却不出汗。","我这一受凉就上吐下泻，背脖子板得难受，脉浮紧。","恶寒无汗，项背僵，胃里翻江倒海直想吐，还拉肚子。"],"differentials":["葛根汤","小半夏汤"],"difficulty":"难点","tags":["呕吐","下利","项强","恶寒","脉浮紧"]},{"id":"F093","no":93,"name":"小柴胡汤加减（太阳少阳）","alias":[],"source":"伤寒论","meridians":["太阳","少阳"],"subPattern":"太阳少阳合病","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":"姜制"},{"herb":"人参","gram":6,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"生姜","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":""},{"herb":"桂枝","gram":9,"processing":""}],"pathogenesis":"太阳表邪未解，邪入少阳，枢机不利，表里同病","standardSymptom":"寒热往来，发热恶寒，胸胁苦满，呕恶，苔薄白，脉弦。","variants":["一阵冷一阵热，冷时发抖热时烧，两边肋胀还犯恶心。","感冒拖着不好，忽冷忽热，胸口闷胀想吐，脉跳得弦。","外头怕冷里头烦热，胁下堵得慌，吃啥都想呕。"],"differentials":["小柴胡汤","桂枝汤"],"difficulty":"进阶","tags":["寒热往来","胸胁苦满","呕恶","恶寒","脉弦"]},{"id":"F094","no":94,"name":"大柴胡汤","alias":[],"source":"伤寒论","meridians":["少阳","阳明"],"subPattern":"少阳阳明合病","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"芍药","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":"姜制"},{"herb":"生姜","gram":15,"processing":""},{"herb":"枳实","gram":9,"processing":""},{"herb":"大枣","gram":12,"processing":""},{"herb":"大黄","gram":6,"processing":"后下"}],"pathogenesis":"少阳不和，阳明腑实，枢机不利而兼里热结","standardSymptom":"往来寒热，胸胁苦满，呕不欲食，心下急痛，便秘，苔黄，脉弦有力。","variants":["忽冷忽热，胃脘又堵又疼，便秘好几天，脉弦得硬。","两边肋胀满，心里急得慌，吃不下还便秘，舌苔黄。","我这毛病寒热交作，心口窝按着剧痛，解不出大便。"],"differentials":["小柴胡汤","大承气汤"],"difficulty":"进阶","tags":["寒热往来","心下急","便秘","呕","苔黄"]},{"id":"F095","no":95,"name":"治中汤","alias":[],"source":"医学启源","meridians":["太阴","阳明"],"subPattern":"脾胃气虚","composition":[{"herb":"人参","gram":9,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"干姜","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"陈皮","gram":6,"processing":""},{"herb":"青皮","gram":6,"processing":""}],"pathogenesis":"中焦虚寒，脾胃气虚，运化无力，气机痞滞","standardSymptom":"脘腹痞满，食少便溏，倦怠乏力，舌淡苔白，脉虚弱。","variants":["胃里老是胀闷不舒，吃不多就饱，大便稀溏，人懒得动。","中焦虚寒，吃点凉的就泻，浑身没劲，舌头淡白。","我这脾胃弱得很，饭量小还老拉肚子，脉虚得软。"],"differentials":["理中汤","香砂六君子汤"],"difficulty":"难点","tags":["脘痞","食少","便溏","乏力","脉弱"]},{"id":"F096","no":96,"name":"附子粳米汤","alias":[],"source":"伤寒论","meridians":["太阴","少阴"],"subPattern":"脾阳虚，肠滑","composition":[{"herb":"附子","gram":9,"processing":"炮"},{"herb":"半夏","gram":9,"processing":"姜制"},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":""},{"herb":"粳米","gram":30,"processing":""}],"pathogenesis":"脾肾阳虚，寒凝气滞，肠鸣泄泻，腹中雷鸣","standardSymptom":"腹中雷鸣切痛，胸胁逆满，呕吐，大便溏泄，舌淡苔白滑，脉沉迟。","variants":["肚子里咕噜咕噜响还绞着疼，又吐又泻，脉沉得迟。","肠子像打雷，冷痛想吐，稀便止不住，舌淡白滑。","我这腹中雷鸣剧痛，吐清水，拉肚子，手脚也凉。"],"differentials":["理中汤","桃花汤"],"difficulty":"难点","tags":["肠鸣","腹痛","呕吐","泄泻","脉沉迟"]},{"id":"F097","no":97,"name":"旋复花代赭石汤","alias":[],"source":"伤寒论","meridians":["阳明","少阳"],"subPattern":"气机阻滞","composition":[{"herb":"旋复花","gram":9,"processing":"包煎"},{"herb":"代赭石","gram":15,"processing":"先煎"},{"herb":"半夏","gram":9,"processing":"姜制"},{"herb":"生姜","gram":15,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":""}],"pathogenesis":"胃虚痰阻，肝胃气逆，噫气不除，气机痞塞","standardSymptom":"心下痞硬，嗳气频作，呕恶，纳差，舌淡苔白腻，脉弦滑。","variants":["胃里堵得硬，老嗳气止不住，吃不下饭，舌苔腻。","我这膈儿老往上顶气，心口下头痞硬，脉滑弦的。","嗳气声连连，胃脘胀满按之硬，恶心不想吃。"],"differentials":["半夏泻心汤","橘皮竹茹汤"],"difficulty":"难点","tags":["嗳气","心下痞","呕恶","纳差","脉弦滑"]},{"id":"F098","no":98,"name":"小陷胸汤","alias":[],"source":"伤寒论","meridians":["阳明","少阳"],"subPattern":"热结胸中","composition":[{"herb":"黄连","gram":6,"processing":""},{"herb":"半夏","gram":12,"processing":"姜制"},{"herb":"瓜蒌","gram":30,"processing":""}],"pathogenesis":"痰热互结，胸脘痞闷，热邪结于上焦胸中","standardSymptom":"心下痞闷，按之则痛，胸闷口苦，舌红苔黄腻，脉滑数。","variants":["心口下头一按就疼，闷得慌还口苦，舌红苔黄腻。","我这胸脘堵痛，按上去更疼，痰多黄黏，脉滑数。","胃脘部痞闷，一按就疼，嘴里发苦发黏，舌头黄腻。"],"differentials":["大陷胸汤","半夏泻心汤"],"difficulty":"难点","tags":["心下痛","痞硬","胸闷","口苦","苔黄腻"]},{"id":"F099","no":99,"name":"柴胡黄芩半夏生姜汤","alias":[],"source":"伤寒论","meridians":["少阳","太阴"],"subPattern":"少阳脾虚","composition":[{"herb":"柴胡","gram":12,"processing":""},{"herb":"黄芩","gram":9,"processing":""},{"herb":"半夏","gram":9,"processing":"姜制"},{"herb":"生姜","gram":9,"processing":""},{"herb":"人参","gram":6,"processing":""},{"herb":"白术","gram":9,"processing":""},{"herb":"甘草","gram":6,"processing":"炙"},{"herb":"大枣","gram":12,"processing":""}],"pathogenesis":"少阳邪郁，太阴脾虚，枢机不利，运化失司","standardSymptom":"往来寒热，胸胁不适，纳差腹胀，便溏乏力，舌淡红苔薄，脉弦弱。","variants":["一阵寒热，胁下不舒，吃不下还腹胀溏便，人乏力。","少阳病兼脾虚，忽冷忽热，胃弱拉肚子，脉虚弦。","我这两边肋胀，饭量小肚子胀，大便稀，没精神。"],"differentials":["小柴胡汤","逍遥散"],"difficulty":"难点","tags":["寒热往来","纳差","腹胀","便溏","脉弦弱"]},{"id":"F100","no":100,"name":"痛泻要方","alias":[],"source":"医学启源","meridians":["太阴","厥阴"],"subPattern":"脾虚肝旺，肝脾不和","composition":[{"herb":"白术","gram":12,"processing":"炒"},{"herb":"白芍","gram":9,"processing":"炒"},{"herb":"陈皮","gram":9,"processing":""},{"herb":"防风","gram":6,"processing":""}],"pathogenesis":"脾虚肝乘，肝脾不和——王绵之将痛泻要方归入和解剂，强调其补脾柔肝、祛湿止泻之功，证属土虚木乘","standardSymptom":"肠鸣腹痛，大便泄泻，泻必腹痛，泻后痛缓，情志不舒则发，舌淡红苔薄白，脉两关不调，左弦而右缓。","variants":["一肚子疼就得跑厕所，拉完反倒舒坦了，跟情绪还有关，一着急就犯。","我这腹泻怪得很，疼一阵泻一阵，泻完不疼了，爱生气时犯，肠子还咕噜响。","肠鸣腹泻，左手的脉弦、右手的脉缓——脾虚还肝克着。"],"differentials":["逍遥散","四逆散"],"difficulty":"进阶","tags":["腹痛","腹泻","泻后痛缓","肠鸣","情志","脉左弦右缓","肝脾不和","和解剂"]}];
